main() {
    // 十进制字面量
    let decimal = 42
    println("十进制 42 = ${decimal}")

    // 不同进制表示同一个值
    let hex = 0x2A        // 十六进制
    let binary = 0b101010  // 二进制
    println("十六进制 0x2A = ${hex}")
    println("二进制 0b101010 = ${binary}")

    // 使用下划线提高可读性
    let million = 1_000_000
    println("一百万 = ${million}")

    // 使用后缀指定类型
    let small: Int8 = 127
    let unsigned: UInt64 = 100u64
    println("Int8: ${small}, UInt64: ${unsigned}")

    // 验证 Int64 是默认类型
    let inferred = 999
    println("推断类型: ${inferred}")
}

main() {
    // 浮点数基本运算
    let distance = 5.5       // 默认 Float64
    let time = 2.0
    let speed = distance / time
    println("距离: ${distance} km")
    println("时间: ${time} h")
    println("平均速度: ${speed} km/h")

    // 科学计数法
    let scientific = 2.4e-1  // 0.24
    println("科学计数法 2.4e-1 = ${scientific}")

    // 使用后缀指定类型
    let pi: Float32 = 3.14159f32
    let e = 2.718f64
    println("π ≈ ${pi}")
    println("e ≈ ${e}")

    // 十六进制浮点字面量
    let hexFloat = 0x1.1p0   // 1.0625
    println("十六进制浮点 0x1.1p0 = ${hexFloat}")

    // 浮点运算
    let avg = (72.5 + 81.0) / 2.0
    println("平均成绩: ${avg}")
}

main() {
    // 布尔字面量
    let isActive = true
    let isAdmin = false
    println("活跃用户: ${isActive}")
    println("管理员: ${isAdmin}")

    // 逻辑非操作
    println("NOT true = ${!isActive}")
    println("NOT false = ${!isAdmin}")

    // 逻辑与和或
    println("true && false = ${isActive && isAdmin}")
    println("true || false = ${isActive || isAdmin}")

    // 短路求值演示
    func getValue(): Bool {
        println("  getValue() 被调用了")
        true
    }
    
    println("短路求值示例:")
    let r1 = false && getValue()  // getValue 不会被调用
    println("false && getValue() 后 getValue 未被调用")
    
    let r2 = true || getValue()   // getValue 不会被调用
    println("true || getValue() 后 getValue 未被调用")

    // 比较操作产生布尔值
    let x = 10
    let y = 20
    println("${x} > ${y}: ${x > y}")
    println("${x} < ${y}: ${x < y}")
    println("${x} == ${y}: ${x == y}")
    println("${x} != ${y}: ${x != y}")
}

main() {
    // Unit 类型：println 返回 Unit
    let result: Unit = println("println 的返回值是 Unit")
    println("Unit 的值: ${result}")
    
    // Unit 的唯一值是 ()
    let empty: Unit = ()
    println("空值: ${empty}")
    
    // 赋值表达式的类型也是 Unit
    var x = 10
    let assignResult = (x = 20)
    println("赋值后 x = ${x}")
    println("赋值表达式的结果: ${assignResult}")

    // Nothing 类型用于控制流
    // break、continue、return 的类型是 Nothing
    println("开始循环")
    for (i in 0..5) {
        if (i == 3) {
            println("遇到 i=3，执行 break")
            break  // break 的类型是 Nothing
            // break 之后的代码不会执行
            println("这行不会打印")
        }
        println("i = ${i}")
    }
    println("循环结束")

    // Nothing 是所有类型的子类型，可以用于灵活的类型推断
    func assertPositive(n: Int64): Unit {
        if (n < 0) {
            throw IllegalArgumentException("n 必须为正数")
            // throw 的类型是 Nothing，因此函数返回 Unit
        }
        println("${n} 是正数")
    }
    
    assertPositive(42)
}

