main() {
    // 定义两个 Option 类型的变量
    let a: ?Int64 = Some(42)
    let b: ?Int64 = None

    // 基本的 if-let 解包
    if (let Some(value) <- a) {
        println("a 的值: ${value}")
    } else {
        println("a 为空")
    }

    if (let Some(value) <- b) {
        println("b 的值: ${value}")
    } else {
        println("b 为空")
    }

    // if-let 配合额外条件检查
    let x: ?Int64 = Some(10)
    if (let Some(v) <- x && v > 5) {
        println("x 的值 ${v} 大于 5")
    } else {
        println("x 为空或值不大于 5")
    }

    // 多个 let pattern 组合
    let p: ?Int64 = Some(3)
    let q: ?Int64 = Some(5)
    if (let Some(m) <- p && let Some(n) <- q) {
        println("p + q = ${m + n}")
    }

    // 使用 || 连接（不绑定变量）
    let r: ?Int64 = None
    if (let Some(_) <- a || let Some(_) <- r) {
        println("a 或 r 至少有一个非空")
    }
}

main() {
    // while 循环：计算 1 到 10 的和
    var i = 1
    var sum = 0
    while (i <= 10) {
        sum += i
        i++
    }
    println("1 到 10 的和: ${sum}")
    
    // do-while 循环：至少执行一次
    var n = 100
    var count = 0
    do {
        println("do-while 循环执行第 ${count + 1} 次")
        count++
    } while (n < 10)  // 条件为假，但循环体仍会执行一次
    
    // 典型应用：不断除以 2 直到为 0
    var num = 100
    var divisions = 0
    while (num > 0) {
        num /= 2
        divisions++
    }
    println("100 需要除以 2 共 ${divisions} 次才能变为 0")
}

main() {
