// 函数是一等公民，可以有类型、赋值给变量、作为参数传递

func double(x: Int64): Int64 {
    x * 2
}

func square(x: Int64): Int64 {
    x * x
}

// 函数类型作为参数类型
func apply(f: (Int64) -> Int64, value: Int64): Int64 {
    f(value)
}

main() {
    // 将函数赋值给变量
    let fn: (Int64) -> Int64 = double
    println("fn(5) = ${fn(5)}")
    
    // 函数作为参数传递
    println("apply(double, 4) = ${apply(double, 4)}")
    println("apply(square, 4) = ${apply(square, 4)}")
    
    // 用 var 声明可以重新赋值
    var operation = double
    println("operation(3) = ${operation(3)}")
    operation = square
    println("operation(3) = ${operation(3)}")
}

// Lambda 表达式：匿名函数的简洁写法

func apply(f: (Int64) -> Int64, value: Int64): Int64 {
    f(value)
}

main() {
    // Lambda 赋值给变量（参数类型可省略）
    let double = { x: Int64 => x * 2 }
    println("double(5) = ${double(5)}")
    
    // 多行 Lambda：if 表达式也是表达式
    let abs = { x: Int64 =>
        if (x < 0) { -x } else { x }
    }
    println("abs(-3) = ${abs(-3)}")
    println("abs(7) = ${abs(7)}")
    
    // Lambda 作为函数参数直接传入
    let result = apply({ x: Int64 => x * 3 }, 4)
    println("apply(三倍函数, 4) = ${result}")
    
    // 无参数 Lambda
    let greet = { => "Hello, Lambda!" }
    println(greet())
    
    // Lambda 立即调用
    let sum = { a: Int64, b: Int64 => a + b }(10, 20)
    println("立即调用结果: ${sum}")
}

// 闭包：捕获外层变量的函数

class CounterState {
    var count: Int64

    init(count: Int64) {
        this.count = count
    }
}

func makeAdder(base: Int64): (Int64) -> Int64 {
    // Lambda 捕获了参数 base
    { value: Int64 => value + base }
}

func makeCounter(start: Int64): () -> Int64 {
    let state = CounterState(start)

    // 逃逸闭包不能直接捕获局部 var；改为捕获不可变的类引用，
    // 再更新该引用指向对象的可变成员。
    func increment(): Int64 {
        state.count = state.count + 1
        state.count
    }
    
    return increment
}

func makeGreeter(prefix: String): () -> String {
    let saved = prefix
    // 返回的 Lambda 捕获了 saved
    { => "${saved}, Cangjie!" }
}

main() {
    // 创建两个独立的闭包
    let add10 = makeAdder(10)
    let add20 = makeAdder(20)
    
    println("add10(5) = ${add10(5)}")  // 15
    println("add20(5) = ${add20(5)}")  // 25
    
    // 闭包各持有独立的捕获值
    println("add10(8) = ${add10(8)}")  // 18

    // 捕获的引用可以在多次调用之间保存可变状态
    let counter = makeCounter(0)
    println("counter() = ${counter()}")  // 1
    println("counter() = ${counter()}")  // 2
    
    // 字符串闭包
    let greetHello = makeGreeter("你好")
    let greetHi = makeGreeter("嗨")
    
    println(greetHello())
    println(greetHi())
}

// 嵌套函数：在函数内部定义的函数

class CounterState {
    var count: Int64

    init(count: Int64) {
        this.count = count
    }
}

func processNumbers(numbers: Array<Int64>): (Int64, Int64, Int64) {
    // 嵌套函数：计算总和
    func sum(arr: Array<Int64>): Int64 {
        var total = 0
        for (n in arr) {
            total += n
        }
        total
    }
    
    // 嵌套函数：计算平均值
    func average(arr: Array<Int64>): Int64 {
        if (arr.size == 0) {
            0
        } else {
            sum(arr) / arr.size
        }
    }
    
    // 嵌套函数：找出最大值
    func max(arr: Array<Int64>): Int64 {
        if (arr.size == 0) {
            0
        } else {
            var maxVal = arr[0]
            for (n in arr) {
                if (n > maxVal) {
                    maxVal = n
                }
            }
            maxVal
        }
    }
    
    // 嵌套函数可以互相调用
    (sum(numbers), average(numbers), max(numbers))
}

func makeCounter(): () -> Int64 {
    let state = CounterState(0)

    // 嵌套函数捕获不可变引用，其指向对象的成员仍可修改
    func increment(): Int64 {
        state.count = state.count + 1
        state.count
    }
    
    increment
}

main() {
    let data = [10, 20, 30, 40, 50]
    let (total, avg, maximum) = processNumbers(data)
    
    println("数据: ${data}")
    println("总和: ${total}")
    println("平均值: ${avg}")
    println("最大值: ${maximum}")
    
    // 嵌套函数作为闭包返回
    let counter = makeCounter()
    println("计数: ${counter()}")  // 1
    println("计数: ${counter()}")  // 2
    println("计数: ${counter()}")  // 3
}

// 函数重载：同名函数，不同参数

func format(value: Int64): String {
    "整数: ${value}"
}

func format(value: Float64): String {
    "浮点数: ${value}"
}

func format(value: String): String {
    "字符串: \"${value}\""
}

// 参数个数不同
func format(a: Int64, b: Int64): String {
    "整数对: (${a}, ${b})"
}

// 布尔类型重载
func format(value: Bool): String {
    "布尔值: ${value}"
}

// 数组类型重载
func format(values: Array<Int64>): String {
    var result = "数组: ["
    for (i in 0..values.size) {
        result = result + "${values[i]}"
        if (i < values.size - 1) {
            result = result + ", "
        }
    }
    result + "]"
}

main() {
    // 编译器根据实参类型选择重载版本
    println(format(42))              // 整数版本
    println(format(3.14159))         // 浮点数版本
    println(format("hello"))         // 字符串版本
    println(format(1, 2))            // 双整数版本
    println(format(true))            // 布尔版本
    println(format([1, 2, 3, 4, 5])) // 数组版本
}

// 尾随 Lambda：函数调用的语法糖

func myIf(flag: Bool, onTrue: () -> Int64): Int64 {
    if (flag) {
        onTrue()
    } else {
        0
    }
}

func applyTwice(action: (Int64) -> Int64): Int64 {
    action(action(2))
}

func repeat(n: Int64, action: (Int64) -> Unit): Unit {
    for (i in 1..=n) {
        action(i)
    }
}

main() {
    // 常规调用
    println(myIf(true, { => 100 }))
    
    // 尾随 Lambda：更清晰的写法
    println(myIf(true) {
        100
    })
    
    // 只有一个函数参数时，括号可省略
    println(applyTwice { value => value + 3 })
    
    // 等价于
    println(applyTwice({ value: Int64 => value + 3 }))
    
    // 常见模式：重复执行
    repeat(3) { i =>
        println("第 ${i} 次执行")
    }
    
    // 组合使用
    let result = myIf(5 > 3) {
        let x = 10
        x * 2
    }
    println("条件结果: ${result}")
}

