// 定义一个表示方向的枚举类型
enum Direction {
    | North
    | South
    | East
    | West
}

// 使用 match 表达式处理枚举的所有情况
func describe(dir: Direction): String {
    match (dir) {
        case North => "向北走"
        case South => "向南走"
        case East => "向东走"
        case West => "向西走"
    }
