open class Animal {
    public open func speak(): String {
        "动物发出的声音"
    }
}

// 狗类
class Dog <: Animal {
    public override func speak(): String {
        "汪汪汪!"
    }

    public func fetch(): String {
        "狗捡回了球"
    }
}

// 猫类
class Cat <: Animal {
    public override func speak(): String {
        "喵喵喵~"
    }

    public func climb(): String {
        "猫爬上了树"
    }
}

// 处理动物的函数
func handleAnimal(a: Animal) {
    println("动物说话: ${a.speak()}")

    // 使用 is 判断运行时类型
    println("是狗吗? ${a is Dog}")
    println("是猫吗? ${a is Cat}")

    // 使用 as 安全转换并访问特有方法
    match (a as Dog) {
        case Some(dog) => 
            println("狗特有动作: ${dog.fetch()}")
        case None => ()
    }

    match (a as Cat) {
        case Some(cat) =>
            println("猫特有动作: ${cat.climb()}")
        case None => ()
    }
}

// 批量处理动物
func processAnimals(animals: Array<Animal>) {
    var dogCount = 0
    var catCount = 0

    for (a in animals) {
        if (a is Dog) {
            dogCount++
        } else if (a is Cat) {
            catCount++
        }
    }

    println("统计: ${dogCount} 条狗, ${catCount} 只猫")
}

main() {
    println("=== 类型判断和转换 ===\n")

    // 创建不同的动物
    let dog: Animal = Dog()  // 声明类型是 Animal
    let cat: Animal = Cat()
    let generic = Animal()

    println("--- 处理狗 ---")
    handleAnimal(dog)

    println("\n--- 处理猫 ---")
    handleAnimal(cat)

    println("\n--- 处理普通动物 ---")
    handleAnimal(generic)

    // 批量处理
    let zoo: Array<Animal> = [
        Dog(), Cat(), Dog(), Animal(), Cat()
    ]
    println("\n=== 动物园统计 ===")
    processAnimals(zoo)
}

// Any 可以持有任何类型的值
func printValue(value: Any) {
    match (value) {
        case i: Int64 => 
            println("整数: ${i}，平方: ${i * i}")
        case f: Float64 =>
            println("浮点数: ${f}，四舍五入: ${f}")
        case s: String =>
            println("字符串: \"${s}\"，长度: ${s.size}")
        case b: Bool =>
            println("布尔值: ${b}，取反: ${!b}")
        case _ => 
            println("其他类型的值")
    }
}

// 灵活的数据容器
class Box {
    let value: Any

    init(value: Any) {
        this.value = value
    }

    func describe(): String {
        match (value) {
            case i: Int64 => "整数盒子[${i}]"
            case s: String => "字符串盒子[${s}]"
            case arr: Array<Any> => "盒子数组，长度${arr.size}"
            case _ => "未知盒子"
        }
    }

    // 尝试获取整数值
    func getInt(): Option<Int64> {
        match (value) {
            case i: Int64 => Some(i)
            case _ => None
        }
    }
}

// 处理混合类型数据
func sumNumbers(values: Array<Any>) {
    var total: Int64 = 0
    for (v in values) {
        match (v) {
            case i: Int64 => total += i
            case f: Float64 => total += Int64(f)
            case _ => ()  // 忽略非数值
        }
    }
    println("总和: ${total}")
}

main() {
    println("=== Any 类型演示 ===\n")

    // Any 可以持有任何值
    printValue(42)
    printValue(3.14159)
    printValue("你好，仓颉")
    printValue(true)
    printValue(Dog())  // 自定义类型

    // 可变长数据混合存储
    println("\n=== 混合数据容器 ===")
    let mixed: Array<Any> = [
        42, "hello", 3.14, true, [1, 2, 3]
    ]
    
    println("遍历混合数组:")
    for (item in mixed) {
        printValue(item)
    }

    // Box 容器示例
    println("\n=== Box 容器 ===")
    let box1 = Box(123)
    let box2 = Box("仓颉语言")
    println(box1.describe())
    println(box2.describe())

    if (let Some(n) <- box1.getInt()) {
        println("取出的整数: ${n}")
    }

    // 数字求和
    println("\n=== 混合类型求和 ===")
    let numbers: Array<Any> = [10, 20.5, 30, "不是数字", 15, 4.0]
    sumNumbers(numbers)
}

