// 辅助类
class Dog {
    public func toString(): String {
        "一只狗"
    }
}

func readAt(values: Array<Int64>, index: Int64): Int64 {
    values[index]
}

main() {
    let values = [10, 20, 30]

    // 正确顺序：具体类型在前，通用类型在后
    try {
        let item = readAt(values, 10)
        println(item)
    } catch (e: IndexOutOfBoundsException) {
        println("捕获到具体异常：${e.message}")
    } catch (e: Exception) {
        println("捕获到通用异常：${e.message}")
    }

    // 不同的异常类型可以分别处理
    try {
        throw ArithmeticException("除数不能为零")
    } catch (e: ArithmeticException) {
        println("算术异常：${e.message}")
    } catch (e: IllegalArgumentException) {
        println("参数异常：${e.message}")
    } catch (e: Exception) {
        println("其他异常：${e.message}")
    }

    println("程序继续执行...")
}

func requireAdult(age: Int64): Int64 {
    if (age < 18) {
        throw Exception("年龄必须至少 18 岁")
    }
    age
}

func divide(a: Int64, b: Int64): Int64 {
    if (b == 0) {
        throw ArithmeticException("除数不能为零")
    }
    a / b
}

main() {
    // 处理验证异常
    try {
        let age = requireAdult(16)
        println("成年年龄：${age}")
    } catch (e: Exception) {
        println("验证失败：${e.message}")
    }

    // 处理算术异常
    try {
        println("20 / 4 = ${divide(20, 4)}")
        println("20 / 0 = ${divide(20, 0)}")
    } catch (e: ArithmeticException) {
        println("计算错误：${e.message}")
    }

    // 第一个异常被捕获后，程序继续执行
    try {
        let age = requireAdult(25)
        println("验证通过，年龄：${age}")
    } catch (e: Exception) {
        println("验证失败：${e.message}")
    }

    println("程序正常结束")
}

func processFile(filename: String): Unit {
    println("打开文件：${filename}")
    try {
        if (filename.isEmpty()) {
            throw Exception("文件名不能为空")
