// 定义带数据的枚举：不同形状携带不同的参数
enum Shape {
    | Circle(Float64)              // 圆：半径
    | Rectangle(Float64, Float64)  // 矩形：宽和高
    | Triangle(Float64, Float64)   // 三角形：底和高
}

// 计算形状的面积
func area(s: Shape): Float64 {
    match (s) {
        case Circle(r) => 
            3.14159 * r * r
        case Rectangle(w, h) => 
            w * h
        case Triangle(b, h) => 
            0.5 * b * h
    }
}

// 生成形状的描述字符串
func describe(s: Shape): String {
    match (s) {
        case Circle(r) => 
            "圆(半径=${r})"
        case Rectangle(w, h) => 
            "矩形(${w} x ${h})"
        case Triangle(b, h) => 
            "三角形(底=${b}, 高=${h})"
    }
}

