    let shapes = [
        Shape.Circle(5.0),
        Shape.Rectangle(4.0, 6.0),
        Shape.Triangle(3.0, 8.0)
    ]

    // 遍历并输出每个形状的信息
    for (s in shapes) {
        let desc = describe(s)
        let a = area(s)
        println("${desc}, 面积 = ${a}")
    }
}

// 递归枚举：表示算术表达式
enum Expr {
    | Num(Int64)          // 数值
    | Add(Expr, Expr)     // 加法：两个子表达式
    | Mul(Expr, Expr)     // 乘法：两个子表达式
}

// 递归计算表达式的值
func eval(e: Expr): Int64 {
    match (e) {
        case Num(n) => 
            n
        case Add(left, right) => 
            eval(left) + eval(right)
        case Mul(left, right) => 
            eval(left) * eval(right)
    }
}

// 将表达式转换为字符串表示
func show(e: Expr): String {
    match (e) {
        case Num(n) => 
            "${n}"
        case Add(l, r) => 
            "(${show(l)} + ${show(r)})"
        case Mul(l, r) => 
            "(${show(l)} * ${show(r)})"
    }
}

main() {
    // 构造表达式: (2 + 3) * 4
    let expr1 = Expr.Mul(
        Expr.Add(Expr.Num(2), Expr.Num(3)),
        Expr.Num(4)
    )
    println("${show(expr1)} = ${eval(expr1)}")

    // 构造表达式: 1 + (2 * 3)
    let expr2 = Expr.Add(
        Expr.Num(1),
        Expr.Mul(Expr.Num(2), Expr.Num(3))
    )
    println("${show(expr2)} = ${eval(expr2)}")

    // 构造表达式: (10 + 20) * (3 + 4)
    let expr3 = Expr.Mul(
        Expr.Add(Expr.Num(10), Expr.Num(20)),
        Expr.Add(Expr.Num(3), Expr.Num(4))
    )
    println("${show(expr3)} = ${eval(expr3)}")
}

// 在数组中查找目标值的索引
func findIndex(arr: Array<Int64>, target: Int64): Option<Int64> {
    for (i in 0..arr.size) {
        if (arr[i] == target) {
            return Some(i)  // 找到，返回索引
        }
    }
    None  // 未找到
}

// 安全的除法运算
func divide(a: Float64, b: Float64): Option<Float64> {
    if (b == 0.0) {
        None  // 除数为零，返回 None
    } else {
        Some(a / b)
    }
}

main() {
    let numbers = [10, 20, 30, 40, 50]

    // 查找存在的值
    match (findIndex(numbers, 30)) {
        case Some(idx) => 
            println("找到 30，索引为 ${idx}")
        case None => 
            println("未找到 30")
    }

    // 查找不存在的值
    match (findIndex(numbers, 99)) {
        case Some(idx) => 
            println("找到 99，索引为 ${idx}")
        case None => 
            println("未找到 99")
    }

    // 正常除法
    match (divide(10.0, 3.0)) {
        case Some(result) => 
            println("10 / 3 = ${result}")
        case None => 
            println("除法失败")
    }

    // 除以零
    match (divide(10.0, 0.0)) {
        case Some(result) => 
