// 泛型函数：类型参数在函数名后的尖括号中声明
func pickFirst<T>(left: T, _: T): T {
    left
}

// 泛型函数可以有多个类型参数
func swap<T, U>(pair: (T, U)): (U, T) {
    let (first, second) = pair
    (second, first)
}

main() {
    // 显式指定类型实参
    let result1 = pickFirst<Int64>(10, 20)
    println("第一个值: ${result1}")

    // 也可以让编译器推断类型
    let result2 = pickFirst("hello", "world")
    println("第一个字符串: ${result2}")

    // 交换元组的元素顺序
    let pair1: (String, Int64) = ("年龄", 18)
    let swapped = swap<String, Int64>(pair1)
    let (swappedAge, swappedLabel) = swapped
    println("交换后: (${swappedAge}, ${swappedLabel})")

    // 使用类型推断
    let pair2 = ("分数", 95)
    let swapped2 = swap(pair2)
    let (swappedScore, swappedScoreLabel) = swapped2
    println("交换后: (${swappedScore}, ${swappedScoreLabel})")
}

// 泛型结构体：存储两个可能不同类型的值
struct Pair<T, U> {
    let first: T
    let second: U

    public init(first: T, second: U) {
        this.first = first
        this.second = second
    }

    public func firstValue(): T {
        first
    }

    public func secondValue(): U {
        second
    }

    // 返回一个新的 Pair，交换元素顺序
    public func swap(): Pair<U, T> {
        Pair<U, T>(second, first)
    }
}

main() {
    // 创建一个 Pair<String, Int64> 实例
    let pair1 = Pair<String, Int64>("成绩", 95)
    println("第一个: ${pair1.firstValue()}")
    println("第二个: ${pair1.secondValue()}")

    // 交换元素顺序
    let swapped = pair1.swap()
    println("交换后 - 第一个: ${swapped.firstValue()}")
    println("交换后 - 第二个: ${swapped.secondValue()}")

    // 创建另一个不同类型的 Pair
    let pair2 = Pair<Bool, String>(true, "已完成")
    println("状态: ${pair2.firstValue()}, 描述: ${pair2.secondValue()}")
}

import std.collection.ArrayList

// 泛型类：实现一个简单的栈结构
class Stack<T> {
    let items = ArrayList<T>()

    public func push(item: T) {
        items.add(item)
    }

    public func pop(): ?T {
        if (items.size == 0) {
            return None
        }
        let lastIndex = items.size - 1
        let value = items[lastIndex]
        items.remove(at: lastIndex)
        return Some(value)
    }

    public func peek(): ?T {
        if (items.size == 0) {
            return None
        }
        return Some(items[items.size - 1])
    }

    public func size(): Int64 {
        items.size
    }

    public func isEmpty(): Bool {
        items.size == 0
    }
}

main() {
    // 创建一个 Stack<Int64> 实例
    let intStack = Stack<Int64>()
    intStack.push(10)
    intStack.push(20)
    intStack.push(30)

    println("栈大小: ${intStack.size()}")
    println("栈顶元素: ${intStack.peek()}")

    // 弹出元素
    match (intStack.pop()) {
        case Some(value) => println("弹出: ${value}")
        case None => println("栈为空")
    }

    println("弹出后大小: ${intStack.size()}")

    // 创建一个 Stack<String> 实例
    let strStack = Stack<String>()
    strStack.push("仓颉")
    strStack.push("编程语言")

    match (strStack.pop()) {
        case Some(value) => println("弹出字符串: ${value}")
        case None => println("栈为空")
    }
}

// 泛型接口：定义值的容器
interface Container<T> {
    func get(): T
    func describe(): String
}

// 泛型结构体实现泛型接口
struct Box<T> <: Container<T> {
    let value: T

    public init(value: T) {
        this.value = value
    }

    public func get(): T {
        value
    }

    public func describe(): String {
        "Box 包含一个值"
    }
}

// 另一个泛型接口实现
struct NamedBox<T> <: Container<T> {
    let value: T
    let name: String

    public init(value: T, name: String) {
        this.value = value
        this.name = name
    }

    public func get(): T {
        value
    }

    public func describe(): String {
        "${name} 包含一个值"
    }
}

// 接受泛型接口作为参数的函数
func showIntContainer(item: Container<Int64>) {
    println("描述: ${item.describe()}")
    println("值: ${item.get()}")
}

func showStringContainer(item: Container<String>) {
    println("描述: ${item.describe()}")
    println("值: ${item.get()}")
}

main() {
    // 创建 Container<Int64> 实例
    let intBox = Box<Int64>(42)
    let intNamed = NamedBox<Int64>(100, "计数器")

    showIntContainer(intBox)
    showIntContainer(intNamed)

    println("---")

    // 创建 Container<String> 实例
    let strBox = Box<String>("仓颉")
    let strNamed = NamedBox<String>("编程语言", "语言名称")

    showStringContainer(strBox)
    showStringContainer(strNamed)
}

import std.collection.*

// 泛型枚举：表示可能成功或失败的结果
enum Result<T, E> {
    | Ok(T)        // 成功，携带类型为 T 的值
    | Err(E)       // 失败，携带类型为 E 的错误
}

// 使用泛型枚举处理除法
func safeDivide(a: Int64, b: Int64): Result<Int64, String> {
    if (b == 0) {
        return Err("除数不能为零")
    }
    return Ok(a / b)
}

// 处理 Result 的函数
func processResult(result: Result<Int64, String>) {
    match (result) {
        case Ok(value) =>
            println("成功: 结果是 ${value}")
        case Err(message) =>
            println("错误: ${message}")
    }
}

// 使用泛型枚举表示可能存在或不存在的值
func findValue(key: String, data: HashMap<String, Int64>): Result<Int64, String> {
    if (data.contains(key)) {
        return Ok(data.get(key).getOrThrow())
    }
    return Err("找不到键: ${key}")
}

main() {
    // 测试安全除法
    let r1 = safeDivide(10, 3)
    processResult(r1)

    let r2 = safeDivide(10, 0)
    processResult(r2)

    println("---")

    // 测试查找值
    let scores = HashMap<String, Int64>([
        ("张三", 85),
        ("李四", 92),
        ("王五", 78)
    ])

    let r3 = findValue("张三", scores)
    processResult(r3)

    let r4 = findValue("赵六", scores)
    processResult(r4)
}

// 泛型函数：类型参数在函数名后的尖括号中声明
func pickFirst<T>(left: T, _: T): T {
    left
}

// 泛型函数可以有多个类型参数
func swap<T, U>(pair: (T, U)): (U, T) {
    let (first, second) = pair
    (second, first)
}

main() {
    // 显式指定类型实参
    let result1 = pickFirst<Int64>(10, 20)
    println("第一个值: ${result1}")

    // 也可以让编译器推断类型
    let result2 = pickFirst("hello", "world")
    println("第一个字符串: ${result2}")

    // 交换元组的元素顺序
    let pair1: (String, Int64) = ("年龄", 18)
    let swapped = swap<String, Int64>(pair1)
    let (swappedAge, swappedLabel) = swapped
    println("交换后: (${swappedAge}, ${swappedLabel})")

    // 使用类型推断
    let pair2 = ("分数", 95)
    let swapped2 = swap(pair2)
    let (swappedScore, swappedScoreLabel) = swapped2
    println("交换后: (${swappedScore}, ${swappedScoreLabel})")
}

// 泛型结构体：存储两个可能不同类型的值
struct Pair<T, U> {
    let first: T
    let second: U

    public init(first: T, second: U) {
        this.first = first
        this.second = second
    }

    public func firstValue(): T {
        first
    }

    public func secondValue(): U {
        second
    }

    // 返回一个新的 Pair，交换元素顺序
    public func swap(): Pair<U, T> {
        Pair<U, T>(second, first)
    }
}

main() {
    // 创建一个 Pair<String, Int64> 实例
    let pair1 = Pair<String, Int64>("成绩", 95)
    println("第一个: ${pair1.firstValue()}")
    println("第二个: ${pair1.secondValue()}")

    // 交换元素顺序
    let swapped = pair1.swap()
    println("交换后 - 第一个: ${swapped.firstValue()}")
    println("交换后 - 第二个: ${swapped.secondValue()}")

    // 创建另一个不同类型的 Pair
    let pair2 = Pair<Bool, String>(true, "已完成")
    println("状态: ${pair2.firstValue()}, 描述: ${pair2.secondValue()}")
}

