// 定义一个可打印接口
interface Printable {
    func display(): String
}

// 学生类实现 Printable 接口
class Student <: Printable {
    let name: String
    let grade: Int64

    init(name: String, grade: Int64) {
        this.name = name
        this.grade = grade
    }

    public func display(): String {
        "${name} (年级 ${grade})"
    }
}

// 课程类实现 Printable 接口
class Course <: Printable {
    let title: String

    init(title: String) {
        this.title = title
    }

    public func display(): String {
        "课程: ${title}"
    }
}

// 泛型函数，T 必须实现 Printable 接口
func printItem<T>(item: T): Unit where T <: Printable {
    println(item.display())
}

// 泛型函数处理数组，每个元素都必须实现 Printable
func printAll<T>(items: Array<T>): Unit where T <: Printable {
    println("列表内容:")
    for (item in items) {
        println("  - ${item.display()}")
    }
}

main() {
    // 可以传入任何实现了 Printable 的类型
    let student = Student("张三", 3)
    printItem(student)

    let course = Course("仓颉编程语言")
    printItem(course)

    // 数组也可以处理
    let students = [
        Student("李四", 1),
        Student("王五", 2),
        Student("赵六", 3)
    ]
    printAll(students)
}

// 定义一个开放的可继承类 Animal
open class Animal {
    let name: String

    init(name: String) {
        this.name = name
    }

    public open func speak(): String {
        "${name} 发出声音"
    }
}

// Dog 继承 Animal
class Dog <: Animal {
    init(name: String) {
        super(name)
    }

    public override func speak(): String {
        "${name} 说: 汪汪!"
    }
}

// Cat 继承 Animal
class Cat <: Animal {
    init(name: String) {
        super(name)
    }

    public override func speak(): String {
        "${name} 说: 喵喵!"
    }
}

// 使用类型约束实现多态
// T 必须是 Animal 的子类型
func makeSpeak<T>(animal: T): Unit where T <: Animal {
    println(animal.speak())
}

// 使用基类型数组存储不同子类型
func speakAll(animals: Array<Animal>): Unit {
    println("动物合唱团:")
    for (a in animals) {
        println("  ${a.speak()}")
    }
}

main() {
    let dog = Dog("大黄")
    let cat = Cat("小白")

    // 方法 1: 泛型函数配合约束
    // 每次调用时 T 被实例化为具体类型
    println("=== 单独调用 ===")
    makeSpeak(dog)  // T = Dog
    makeSpeak(cat)  // T = Cat

    // 方法 2: 基类型数组存放多种子类型
    println("\n=== 集体调用 ===")
    let animals: Array<Animal> = [
        Dog("旺财"),
        Cat("咪咪"),
        Dog("小黑"),
        Cat("花花")
    ]
    speakAll(animals)
}

