// 定义可显示接口
interface Displayable {
    func display(): String
}

// 定义可比较接口
interface Comparable<T> {
    func compareTo(other: T): Int64
}

// Score 类同时实现两个接口
class Score <: Displayable & Comparable<Score> {
    let value: Int64
    let subject: String

    init(subject: String, value: Int64) {
        this.subject = subject
        this.value = value
    }

    // 实现 Displayable 接口
    public func display(): String {
        "${subject}: ${value} 分"
    }

    // 实现 Comparable 接口
    public func compareTo(other: Score): Int64 {
        this.value - other.value
    }
}

// 单约束泛型函数：只需要 Comparable
// 返回较大的那个值
func findMax<T>(a: T, b: T): T where T <: Comparable<T> {
    if (a.compareTo(b) > 0) {
        a
    } else {
        b
    }
}

// 双重约束泛型函数：需要 Comparable 和 Displayable
// 找出最大值并显示
func showMax<T>(a: T, b: T): Unit where T <: Comparable<T> & Displayable {
    let max = findMax(a, b)  // 调用单约束函数
    println("最高分: ${max.display()}")
}

// 三重约束示例：比较、显示、还能计数
interface Countable {
    func count(): Int64
}

func process<T>(a: T, b: T): Unit where T <: Comparable<T> & Displayable & Countable {
    println("处理两个项目...")
    println("项目 A: ${a.display()}")
    println("项目 B: ${b.display()}")
    
    let max = findMax(a, b)
    println("较大者: ${max.display()}")
}

main() {
    let math1 = Score("数学", 85)
    let math2 = Score("数学", 92)

    println("比较两次数学成绩:")
    showMax(math1, math2)

    let english1 = Score("英语", 78)
    let english2 = Score("英语", 95)

    println("\n比较两次英语成绩:")
    showMax(english1, english2)
}

import std.collection.*

// 定义可标识接口
interface Identifiable {
    func getId(): String
}

// 泛型注册表类，要求元素实现 Identifiable 接口
class Registry<T> where T <: Identifiable {
    let items = HashMap<String, T>()

    // 注册新元素
    public func register(item: T): Unit {
        items.add(item.getId(), item)
        println("已注册: ID = ${item.getId()}")
    }

    // 根据 ID 查找元素
    public func find(id: String): Option<T> {
        if (items.contains(id)) {
            Some(items[id])
        } else {
            None
        }
    }

    // 移除元素
    public func remove(id: String): Bool {
        if (items.contains(id)) {
            items.remove(id)
            println("已移除: ID = ${id}")
            true
        } else {
            println("未找到: ID = ${id}")
            false
        }
    }

    // 获取总数
    public func count(): Int64 {
        items.size
    }

    // 列出所有 ID
    public func listAll(): Unit {
        println("当前已注册 ${count()} 个项目:")
        for ((id, _) in items) {
            println("  - ${id}")
        }
    }
}

// 用户类实现 Identifiable
class User <: Identifiable {
    let id: String
    let name: String
    let age: Int64

    init(id: String, name: String, age: Int64) {
        this.id = id
        this.name = name
        this.age = age
    }

    public func getId(): String {
        id
    }

    public func info(): String {
        "${name}, ${age} 岁"
    }
}

main() {
    // 创建用户注册表
    let users = Registry<User>()
    println("=== 用户注册系统 ===\n")

    // 注册用户
    users.register(User("u001", "张三", 25))
    users.register(User("u002", "李四", 30))
    users.register(User("u003", "王五", 28))

    // 列出所有用户
    println("")
    users.listAll()

    // 查找用户
    println("\n=== 查找用户 ===")
    match (users.find("u002")) {
        case Some(user) => println("找到: ${user.info()}")
        case None => println("用户不存在")
    }

    match (users.find("u999")) {
        case Some(user) => println("找到: ${user.info()}")
        case None => println("用户 u999 不存在")
    }

    // 移除用户
    println("\n=== 移除用户 ===")
    users.remove("u001")
    users.listAll()
}

// 定义支持编译期构造的结构体
struct Point {
    const Point(let x: Float64, let y: Float64) {}
}

// const 函数：可以在编译期求值
// 计算两点之间的欧氏距离
const func distance(a: Point, b: Point): Float64 {
    let dx = a.x - b.x
    let dy = a.y - b.y
    (dx ** 2 + dy ** 2) ** 0.5
}

// const 函数：计算平方和
const func sumSquares(n: Int64): Int64 {
    if (n <= 0) {
        0
    } else {
        n * n + sumSquares(n - 1)
    }
}

// const 函数：阶乘
const func factorial(n: Int64): Int64 {
    if (n <= 1) {
        1
    } else {
        n * factorial(n - 1)
    }
}

main() {
    // 编译期创建点和计算距离
    const a = Point(3.0, 0.0)      // 编译期构造
    const b = Point(0.0, 4.0)      // 编译期构造
    const d = distance(a, b)       // 编译期计算，结果是 5.0
    
    println("=== 编译期求值 ===")
    println("点 A: (${a.x}, ${a.y})")
    println("点 B: (${b.x}, ${b.y})")
    println("距离: ${d}")

    // 编译期计算数学值
    const sum = sumSquares(10)      // 1² + 2² + ... + 10²
    const fact = factorial(10)      // 10!
    
    println("\n=== 编译期数学计算 ===")
    println("1到10的平方和: ${sum}")
    println("10的阶乘: ${fact}")

    // const 函数也可以在运行时调用
    println("\n=== 运行时计算 ===")
    let p1 = Point(1.0, 2.0)        // 运行时构造
    let p2 = Point(4.0, 6.0)        // 运行时构造
    let dist = distance(p1, p2)     // 运行时计算
    println("运行时距离: ${dist}")
}

