    println("主线程: 等待子线程完成")

    // 等待两个 worker 线程完成
    worker1.get()
    worker2.get()

    println("主线程: 完成")
}

// 计算 [start, end] 区间内所有整数的和
func sumRange(start: Int64, end: Int64): Int64 {
    var total: Int64 = 0
    var current = start
    while (current <= end) {
        total += current
        current += 1
    }
    return total
}

main() {
    println("计算 1 到 100 的和...")

    // 在新线程中计算前半部分
    let left = spawn {
        sumRange(1, 50)
    }

    // 在另一个新线程中计算后半部分
    let right = spawn {
        sumRange(51, 100)
    }

    // 等待两个线程完成并获取结果
    let leftSum = left.get()
    let rightSum = right.get()
    let total = leftSum + rightSum

    println("左半部分 (1-50): ${leftSum}")
    println("右半部分 (51-100): ${rightSum}")
    println("总和: ${total}")
}

import std.sync.SyncCounter

main() {
    // 创建一个计数器作为"门"，初始值为 1
    let gate = SyncCounter(1)

    // 创建 worker 线程
    let worker = spawn {
        println("worker: 等待门打开")
        gate.waitUntilZero()  // 阻塞直到计数器归零

        // 检查是否有取消请求
        if (Thread.currentThread.hasPendingCancellation) {
            println("worker: 收到取消请求，提前退出")
            return
        }

        println("worker: 继续执行任务")
    }

    // 先发送取消请求
    println("主线程: 发送取消请求")
    worker.cancel()

    // 然后打开门（计数器减 1）
    println("主线程: 打开门")
    gate.dec()

    // 等待 worker 线程结束
    worker.get()
    println("主线程: 完成")
}

main() {
    println("倒计时开始...")

    var count = 5
    while (count > 0) {
        println("${count}...")
        
        // 暂停 200 毫秒
        sleep(200 * Duration.millisecond)
        
        count -= 1
    }

    // 最后打印 "go" 之前再暂停一下
    sleep(300 * Duration.millisecond)
    println("go!")
    
    println("倒计时结束")
}

